#![no_std]
#![no_main]

// Direct translation of tools/testing/selftests/bpf/progs/linked_list_fail.c
// (bpf-rs-core idiom).
//
// 117 verifier rejection tests driven by prog_tests/linked_list.c's own
// {prog_name, err_msg} table (test_linked_list_fail_prog(): autoload one
// program, expect the load to fail, strstr the verifier log), not by
// test_loader tags, so there is no test_tags! here. The types and maps are
// linked_list.h's, as in linked_list.rs. The 80 CHECK/CHECK_OP programs
// are generated by the check_* macros below with C's program names; C's
// INIT block is the init! macro (the names it binds are passed in because
// macro_rules! hygiene would otherwise hide them from the body).
//
// ghead and glock (private(A)) and glock2 (private(B)) are C `__hidden`
// statics in `.bss.A`/`.bss.B`, laid out as in the C object: clang emits
// them in first-use order (ghead 0, glock 16; the table expects
// "bpf_spin_lock at off=16" for the global tests), and ghead is declared
// before glock here to match.
//
// C calls bpf_list_pop_front through a `void (*)(void *)` cast only to
// discard the result; the calls here are direct. bpf_obj_new_impl /
// bpf_obj_drop_impl are the kernel's two-argument kfuncs that C's
// bpf_obj_new()/bpf_obj_drop() macros wrap; obj_type_id_oor,
// obj_new_no_composite and obj_new_flex_array call them directly like the
// C does. The anonymous C types (`struct { int data; }` x2, `union { int
// data; unsigned udata; }`, pop_ptr_off's struct) are the named Rust types
// data_only, data_udata and pop_ptr_off_val, declared `(anonymous)` for
// scripts/type_id.py; the verifier's messages never name them.
// obj_new_no_composite's bpf_core_type_id_local(int) is `local int int`.

// BTF_TYPE_ID: foo_id local struct foo
// BTF_TYPE_ID: bar_id local struct bar
// BTF_TYPE_ID: int_id local int int
// BTF_TYPE_ID: data_udata_id local union data_udata (anonymous)
// BTF_TYPE_ID: obj_new_flex_id local struct obj_new_flex
// BTF_TYPE_ID: test1_id local struct test1
// BTF_TYPE_ID: data_only_id local struct data_only (anonymous)
// BTF_TYPE_ID: pop_ptr_off_val_id local struct pop_ptr_off_val (anonymous)

use bpf_rs_core::bpf_object;
use bpf_rs_core::ctx::__sk_buff;
use bpf_rs_core::helpers::{bpf_map_lookup_elem, bpf_spin_lock, bpf_spin_unlock, bpf_this_cpu_ptr};
use btf_macros::btf_tag;
use core::ffi::c_void;
use core::ptr::{addr_of_mut, null_mut};

#[allow(non_camel_case_types)]
#[repr(C)]
struct bpf_spin_lock {
    val: u32,
}

#[allow(non_camel_case_types)]
#[repr(C, align(8))]
struct bpf_list_head {
    __opaque: [u64; 2],
}

#[allow(non_camel_case_types)]
#[repr(C, align(8))]
struct bpf_list_node {
    __opaque: [u64; 3],
}

#[allow(non_camel_case_types)]
#[repr(C)]
struct bar {
    node: bpf_list_node,
    data: i32,
}

#[allow(non_camel_case_types)]
#[btf_tag]
#[repr(C)]
struct foo {
    node: bpf_list_node,
    #[btf_tag(decl_tag = "contains:bar:node")]
    head: bpf_list_head,
    lock: bpf_spin_lock,
    data: i32,
    node2: bpf_list_node,
}

#[allow(non_camel_case_types)]
#[btf_tag]
#[repr(C)]
struct map_value {
    lock: bpf_spin_lock,
    data: i32,
    #[btf_tag(decl_tag = "contains:foo:node2")]
    head: bpf_list_head,
}

// struct array_map { __uint(type, ARRAY); __type(key, int);
// __type(value, struct map_value); __uint(max_entries, 1); }
#[allow(non_camel_case_types)]
#[repr(C)]
struct array_map {
    r#type: *const [i32; 2], // BPF_MAP_TYPE_ARRAY
    key: *const i32,
    value: *const map_value,
    max_entries: *const [i32; 1],
}
unsafe impl Sync for array_map {}

#[link_section = ".maps"]
#[no_mangle]
static array_map: array_map = array_map {
    r#type: core::ptr::null(),
    key: core::ptr::null(),
    value: core::ptr::null(),
    max_entries: core::ptr::null(),
};

#[link_section = ".maps"]
#[no_mangle]
static inner_map: array_map = array_map {
    r#type: core::ptr::null(),
    key: core::ptr::null(),
    value: core::ptr::null(),
    max_entries: core::ptr::null(),
};

// struct { __uint(type, ARRAY_OF_MAPS); __uint(max_entries, 1);
// __type(key, int); __type(value, int); __array(values, struct array_map);
// } map_of_maps = { .values = { [0] = &inner_map } };
// `[T; 1]` emits the slot storage and its .rel.maps entry;
// scripts/btf_map_slots.py rewrites the BTF member to the zero-length array
// libbpf demands.
#[allow(non_camel_case_types)]
#[repr(C)]
struct map_of_maps_def {
    r#type: *const [i32; 12], // BPF_MAP_TYPE_ARRAY_OF_MAPS
    max_entries: *const [i32; 1],
    key: *const i32,
    value: *const i32,
    values: [*const array_map; 1],
}
unsafe impl Sync for map_of_maps_def {}

#[link_section = ".maps"]
#[no_mangle]
static map_of_maps: map_of_maps_def = map_of_maps_def {
    r#type: core::ptr::null(),
    max_entries: core::ptr::null(),
    key: core::ptr::null(),
    value: core::ptr::null(),
    values: [&inner_map],
};

#[allow(non_upper_case_globals)]
#[btf_tag(decl_tag = "contains:foo:node2")]
#[link_section = ".bss.A"]
static mut ghead: bpf_list_head = bpf_list_head { __opaque: [0; 2] };

#[allow(non_upper_case_globals)]
#[link_section = ".bss.A"]
static mut glock: bpf_spin_lock = bpf_spin_lock { val: 0 };

#[allow(non_upper_case_globals)]
#[link_section = ".bss.B"]
static mut glock2: bpf_spin_lock = bpf_spin_lock { val: 0 };

extern "C" {
    fn foo_id() -> u64;
    fn bar_id() -> u64;
    fn int_id() -> u64;
    fn data_udata_id() -> u64;
    fn obj_new_flex_id() -> u64;
    fn test1_id() -> u64;
    fn data_only_id() -> u64;
    fn pop_ptr_off_val_id() -> u64;
    fn bpf_obj_new(local_type_id: u64) -> *mut c_void;
    fn bpf_obj_new_impl(local_type_id: u64, meta: *mut c_void) -> *mut c_void;
    fn bpf_obj_drop(obj: *mut c_void);
    fn bpf_obj_drop_impl(obj: *mut c_void, meta: *mut c_void);
    fn bpf_list_push_front(head: *mut bpf_list_head, node: *mut bpf_list_node) -> i32;
    fn bpf_list_push_back(head: *mut bpf_list_head, node: *mut bpf_list_node) -> i32;
    fn bpf_list_pop_front(head: *mut bpf_list_head) -> *mut bpf_list_node;
    fn bpf_list_pop_back(head: *mut bpf_list_head) -> *mut bpf_list_node;
}

// C's INIT: the map values, two foos and a bar every CHECK program starts
// with (and, failing verification first, never releases).
macro_rules! init {
    ($v:ident, $v2:ident, $iv:ident, $iv2:ident, $f:ident, $f1:ident, $f2:ident, $b:ident) => {
        let zero: i32 = 0;
        let map = bpf_map_lookup_elem(&map_of_maps, &zero);
        if map.is_null() {
            return 0;
        }
        let $v = bpf_map_lookup_elem(&array_map, &zero) as *mut map_value;
        if $v.is_null() {
            return 0;
        }
        let $v2 = bpf_map_lookup_elem(&array_map, &zero) as *mut map_value;
        if $v2.is_null() {
            return 0;
        }
        let $iv = bpf_map_lookup_elem(map, &zero) as *mut map_value;
        if $iv.is_null() {
            return 0;
        }
        let $iv2 = bpf_map_lookup_elem(map, &zero) as *mut map_value;
        if $iv2.is_null() {
            return 0;
        }
        let $f = bpf_obj_new(foo_id()) as *mut foo;
        if $f.is_null() {
            return 0;
        }
        let $f1 = $f;
        let $f2 = bpf_obj_new(foo_id()) as *mut foo;
        if $f2.is_null() {
            bpf_obj_drop($f1.cast());
            return 0;
        }
        let $b = bpf_obj_new(bar_id()) as *mut bar;
        if $b.is_null() {
            bpf_obj_drop($f2.cast());
            bpf_obj_drop($f1.cast());
            return 0;
        }
        let _ = ($v, $v2, $iv, $iv2, $f, $f1, $f2, $b);
    };
}

// CHECK(test, op, hexpr): test_missing_lock_op
macro_rules! check_missing_lock_pop {
    ($name:ident, $op:ident, [$($n:ident),*], $hexpr:expr) => {
        #[link_section = "?tc"]
        #[no_mangle]
        extern "C" fn $name(_ctx: *const c_void) -> i32 {
            unsafe {
                init!($($n),*);
                $op($hexpr);
                0
            }
        }
    };
}

// CHECK(test, op, hexpr, nexpr): test_missing_lock_op
macro_rules! check_missing_lock_push {
    ($name:ident, $op:ident, [$($n:ident),*], $hexpr:expr, $nexpr:expr) => {
        #[link_section = "?tc"]
        #[no_mangle]
        extern "C" fn $name(_ctx: *const c_void) -> i32 {
            unsafe {
                init!($($n),*);
                $op($hexpr, $nexpr);
                0
            }
        }
    };
}

// CHECK(test, op, lexpr, hexpr): test_incorrect_lock_op
macro_rules! check_incorrect_lock_pop {
    ($name:ident, $op:ident, [$($n:ident),*], $lexpr:expr, $hexpr:expr) => {
        #[link_section = "?tc"]
        #[no_mangle]
        extern "C" fn $name(_ctx: *const c_void) -> i32 {
            unsafe {
                init!($($n),*);
                bpf_spin_lock($lexpr);
                $op($hexpr);
                0
            }
        }
    };
}

// CHECK(test, op, lexpr, hexpr, nexpr): test_incorrect_lock_op
macro_rules! check_incorrect_lock_push {
    ($name:ident, $op:ident, [$($n:ident),*], $lexpr:expr, $hexpr:expr, $nexpr:expr) => {
        #[link_section = "?tc"]
        #[no_mangle]
        extern "C" fn $name(_ctx: *const c_void) -> i32 {
            unsafe {
                init!($($n),*);
                bpf_spin_lock($lexpr);
                $op($hexpr, $nexpr);
                0
            }
        }
    };
}

