#[inline(always)]
unsafe fn use_after_unlock(push_front: bool) -> i32 {
    let f = bpf_obj_new(foo_id()) as *mut foo;
    if f.is_null() {
        return 0;
    }
    bpf_spin_lock(addr_of_mut!(glock));
    (*f).data = 42;
    if push_front {
        bpf_list_push_front(addr_of_mut!(ghead), addr_of_mut!((*f).node2));
    } else {
        bpf_list_push_back(addr_of_mut!(ghead), addr_of_mut!((*f).node2));
    }
    bpf_spin_unlock(addr_of_mut!(glock));

    (*f).data
}

