#[inline(always)]
unsafe fn pop_ptr_off(op: unsafe extern "C" fn(*mut bpf_list_head) -> *mut bpf_list_node) -> i32 {
    let p = bpf_obj_new(pop_ptr_off_val_id()) as *mut pop_ptr_off_val;
    if p.is_null() {
        return 0;
    }
    bpf_spin_lock(addr_of_mut!((*p).lock));
    let n = op(addr_of_mut!((*p).head));
    bpf_spin_unlock(addr_of_mut!((*p).lock));

    if n.is_null() {
        return 0;
    }
    bpf_spin_lock(n);
    0
}

